import type { LiturgyBlock } from '../types';

export const blocks: readonly LiturgyBlock[] = [
  {"id": "cu-str-0001", "section": "service", "who": "reader", "text": "В НЕДЕЛЮ ВАИЙ ВЕЧЕРА, На"},
  {"id": "cu-str-0002", "section": "service", "who": "reader", "text": "Господи воззвах,"},
  {"id": "cu-str-0003", "section": "service", "who": "rubric", "text": "поставим стихов 6, и поем самогласны три, повторяюще сия, глас 8:"},
  {"id": "cu-str-0004", "section": "service", "who": "reader", "text": "Радуйся и веселися граде Сионе: / красуйся и радуйся Церкве Божия: / се бо Царь твой прииде в правде, / на жребяти седя, от детей воспеваемый: / осанна в вышних, благословен еси / Имеяй множество щедрот, помилуй нас."},
  {"id": "cu-str-0005", "section": "service", "who": "reader", "text": "Прииде Спас днесь во град Иерусалим, / исполнити Писание / и вси прияша в руки ваиа: / ризы же подстилаху Ему, / ведуще, яко Той есть Бог наш, / Емуже херувими вопиют непрестанно: / осанна в вышних, благословен еси / Имеяй множество щедрот, помилуй нас."},
  {"id": "cu-str-0006", "section": "service", "who": "reader", "text": "На херувимех носимый, и певаемый от серафим, / возсел еси на жребя Давидски Блаже, / и дети Тя воспеваху Боголепно, / иудее же хуляху беззаконно: / стропотное языков, седалище жребца прообразоваше, / из неверия в веру претворяемое: / слава Тебе Христе, / Едине Милостиве и Человеколюбче."},
  {"id": "cu-str-0007", "section": "service", "who": "reader", "text": "Слава: Радуйся и веселися граде Сионе: / красуйся и радуйся Церкве Божия: / се бо Царь твой прииде в правде, / на жребяти седя, от детей воспеваемый: / осанна в вышних, благословен еси / Имеяй множество щедрот, помилуй нас."},
  {"id": "cu-str-0008", "section": "service", "who": "reader", "text": "И ныне: На херувимех носимый, и певаемый от серафим, / возсел еси на жребя Давидски Блаже, / и дети Тя воспеваху Боголепно, / иудее же хуляху беззаконно: / стропотное языков, седалище жребца прообразоваше, / из неверия в веру претворяемое: / слава Тебе Христе, / Едине Милостиве и Человеколюбче."},
  {"id": "cu-str-0009", "section": "service", "who": "rubric", "text": "Вход. Прокимен обычный:"},
  {"id": "cu-str-0010", "section": "service", "who": "reader", "text": "Се ныне благословите:"},
  {"id": "cu-str-0011", "section": "service", "who": "reader", "text": "На стиховне стихиры самогласны, глас 2:"},
  {"id": "cu-str-0012", "section": "service", "who": "reader", "text": "От ветвий и ваий, яко от Божественна праздника, / в Божественный прешедше праздник, / к честному Христовых страстей, / вернии, стецемся таинству спасительному: / и Сего видим за нас страсть терпяща вольную, / Тому же пение подобное / благодаряще воспоим, умильно зовуще: / благоутробия источниче, и спасения пристанище, / Господи слава Тебе. Стих:"},
  {"id": "cu-str-0013", "section": "service", "who": "reader", "text": "Воспойте Господеви песнь нову, яко дивна сотвори Господь. Глас 3:"},
  {"id": "cu-str-0014", "section": "service", "who": "reader", "text": "Страшно еже впасти в руце Бога жива: / Сей судия есть помышлений и мыслей сердечных. / Никтоже да внидет искушаяй веру непорочную, / но в кротости и страсе Христу приступим, / да приимем милость, и благодать обрящем, / во благовременную помощь. Стих:"},
  {"id": "cu-str-0015", "section": "service", "who": "reader", "text": "Видеша вси концы земли спасение Бога нашего. Глас 7:"},
  {"id": "cu-str-0016", "section": "service", "who": "reader", "text": "Сонмице лукавая и прелюбодейная, / своему Мужу не сохраншая веру, / что держиши завет, егоже не была еси наследница? / Что хвалишися о Отце, Сына отвергшаяся? / Пророки не прияла еси, Сына возвестившия. / Поне своих чад усрамися, сице вопиющих: / осанна Сыну Давидову, / благословен Грядый во имя Господне."},
  {"id": "cu-str-0017", "section": "service", "who": "reader", "text": "Слава, глас 2: От ветвий и ваий, яко от Божественна праздника, / в Божественный прешедше праздник, / к честному Христовых страстей, / вернии, стецемся таинству спасительному: / и Сего видим за нас страсть терпяща вольную, / Тому же пение подобное / благодаряще воспоим, умильно зовуще: / благоутробия источниче, и спасения пристанище, / Господи слава Тебе."},
  {"id": "cu-str-0018", "section": "service", "who": "reader", "text": "И ныне, глас 3: Страшно еже впасти в руце Бога жива: / Сей судия есть помышлений и мыслей сердечных. / Никтоже да внидет искушаяй веру непорочную, / но в кротости и страсе Христу приступим, / да приимем милость, и благодать обрящем, / во благовременную помощь."},
  {"id": "cu-str-0019", "section": "service", "who": "reader", "text": "Ныне отпущаеши: И по"},
  {"id": "cu-str-0020", "section": "service", "who": "reader", "text": "Отче наш, тропарь:"},
  {"id": "cu-str-0021", "section": "service", "who": "reader", "text": "Богородице Дево радуйся:"},
  {"id": "cu-str-0022", "section": "service", "who": "rubric", "text": "И прочая яко обычно. И обычныя поклоны."},
  {"id": "cu-str-0023", "section": "service", "who": "rubric", "text": "Вестно буди, яко"},
  {"id": "cu-str-0024", "section": "service", "who": "reader", "text": "Богородице Дево:"},
  {"id": "cu-str-0025", "section": "service", "who": "rubric", "text": "и прочая, со сладкопением поются, во святыя Четыредесятницы Недели, такожде и в настоящую. В прочия же дни Великия седмицы поскору глаголются."},
  {"id": "cu-str-0026", "section": "service", "who": "reader", "text": "Отпуст: Грядый Господь на вольную страсть, нашего ради спасения, Христос, истинный Бог наш, молитвами пречистыя Своея Матере, святых славных и всехвальных Апостол, святых праведных Богоотец Иоакима и Анны, и всех святых, помилует и спасет нас, яко Благ и Человеколюбец."},
  {"id": "cu-str-0027", "section": "service", "who": "reader", "text": "В НЕДЕЛЮ ВАИЙ ВЕЧЕРА"},
  {"id": "cu-str-0028", "section": "service", "who": "rubric", "text": "Повечерие глаголем малое, на немже поем трипеснец господина Андреа Критскаго. Ирмос по дважды. Тропари колико их есть. И последи ирмос оба лика вкупе. Такожде творим и в прочия Великия седмицы вечеры, на Повечерии. Глас 8."},
  {"id": "cu-str-0029", "section": "service", "who": "reader", "text": "Песнь 1. Ирмос:"},
  {"id": "cu-str-0030", "section": "service", "who": "reader", "text": "Сокрушившему брани мышцею Своею / и проведшему Израиля сквозе Чермное море / поим Ему, яко Избавителю нашему Богу, / яко прославися."},
  {"id": "cu-str-0031", "section": "service", "who": "reader", "text": "Иосифово целомудрие подражаим вернии, / разумеим Почетшаго человеческое словесное существо, / всяцем хранением поживше добродетелию действительною."},
  {"id": "cu-str-0032", "section": "service", "who": "reader", "text": "Добрых неделание уподобися смоковнице: / сего убо уклонимся, да не изсхнем якоже она тогда, / соборище листвием покрывающееся преднаписующая."},
  {"id": "cu-str-0033", "section": "service", "who": "reader", "text": "Образ Владычень подписуя Иосиф, в ров ввержен бывает, / продается от сродник, вся терпит приснопамятный, / во образ поистинне Христов."},
  {"id": "cu-str-0034", "section": "service", "who": "reader", "text": "Смоковницы безплодствия убежавше братие, разумеим образ, / да не изсхнем якоже она тогда, / егда возвращаяся Человеколюбец прииде к ней алча."},
  {"id": "cu-str-0035", "section": "service", "who": "reader", "text": "Иисус за мир тщася пострадати волею, / идет со ученики Своими во град Иерусалим к вольней страсти, / юже прииде пострадати."},
  {"id": "cu-str-0036", "section": "service", "who": "reader", "text": "Прилепившеся Господеви вся тщащемуся пострадати, / готови будем на оплевание, на поругания, и на уничижения, / яко да пречистыми Его страстьми спрославимся вернии"},
  {"id": "cu-str-0037", "section": "service", "who": "reader", "text": "Страстьми страсти исцеляет, Пострадавый о нас: / хотя бо производит, на наше существо человеческое, / животворная Своя страдания, да мы спасемся."},
  {"id": "cu-str-0038", "section": "service", "who": "reader", "text": "Слава: Три безначальна прославляю, три Свята пою, / три соприсносущна во едином Существе проповедаю: / Един бо во Отце, Сыне и Дусе славословится Бог."},
  {"id": "cu-str-0039", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Жезл убо Моисеов, и жезл Ааронов, странное претворение, / и паче ума смотрение имеша: / Твое же чрево Богородительнице, / рождество обновляет новое."},
  {"id": "cu-str-0040", "section": "service", "who": "reader", "text": "Седален, глас 4. Подобен: Явился еси:"},
  {"id": "cu-str-0041", "section": "service", "who": "reader", "text": "Смоковницы осуждение да не предварит тя, / но благия плоды потщися / сердца броздами душе Творцу Твоему Христу возвести, / в покаянии Ему приносящи."},
  {"id": "cu-str-0042", "section": "service", "who": "reader", "text": "Песнь 8. Ирмос:"},
  {"id": "cu-str-0043", "section": "service", "who": "reader", "text": "На горе святей прославльшася, / и в купине огнем Приснодевы Моисеови тайну явльшаго, / Господа пойте / и превозносите во вся веки."},
  {"id": "cu-str-0044", "section": "service", "who": "reader", "text": "Целомудрием украсивше житие, / и мудростию сохранивше веру, / правды нравы взыщем, / да в мужестве споследующе, / Христови сраспнемся."},
  {"id": "cu-str-0045", "section": "service", "who": "reader", "text": "Другую Еву обрет египтяныню, / не победися к неподобному деянию патриарх Иосиф, / но ста якоже некий адамант, / от страстей не ят греховных."},
  {"id": "cu-str-0046", "section": "service", "who": "reader", "text": "Преходя житейская шествия Спасе мой, / взалкал еси волею, спасения всех желая: / сего бо взалкал еси, обращения от Тебе удаленных."},
  {"id": "cu-str-0047", "section": "service", "who": "reader", "text": "Праотец вкуш от древа, яко познася наг и посрамлен, / листвие смоковное взем препоясася: / соборище бо обнаженное Христа проображашеся."},
  {"id": "cu-str-0048", "section": "service", "who": "reader", "text": "Готовися душе прежде исхода, / устрой себе ко оному житию: / и Христу тебе ради пострадати тщащемуся, да тя прославит, / потщися спострадати, и сраспятися, и умрети."},
  {"id": "cu-str-0049", "section": "service", "who": "reader", "text": "Како не ужаснется смерть, Спасе мой? / Како не убоится ад сретый Тя, / по благоизволению к страсти тщащагося, / и о неправедных праведна Тя зря пострадати пришедша?"},
  {"id": "cu-str-0050", "section": "service", "who": "reader", "text": "Лазарево востание видевше иудеи, священницы и левити / клятвенное согласие завистию уготовльше, лестию предательства, / Христа предаша на смерть Пилату."},
  {"id": "cu-str-0051", "section": "service", "who": "reader", "text": "Агница Твоя и Раба и Дева, / к страсти Тя устремляющася видящи, / и душу о нас полагающа, добраго Пастыря, / утробою Матернею по Тебе рыдаше."},
  {"id": "cu-str-0052", "section": "service", "who": "reader", "text": "Благословим Отца и Сына, и Святаго Духа, Господа. Троичен:"},
  {"id": "cu-str-0053", "section": "service", "who": "reader", "text": "Яко Единицу Существом пою Тя, / яко Троицу Лицы Тя чту, / Отче, и Сыне, и Душе Пресвятый: / безначальную державу Твоего Царствия славлю во веки."},
  {"id": "cu-str-0054", "section": "service", "who": "reader", "text": "И ныне, Богородичен: Молит Тя Христе Богородица, / молит ученик Твоих собор: / Твой мир даруй мирови Твоему, / и щедроты Твоя подаждь нам богатно во веки."},
  {"id": "cu-str-0055", "section": "service", "who": "reader", "text": "Хвалим, благословим, покланяемся Господеви, поюще, и превозносяще во вся веки. Ирмос:"},
  {"id": "cu-str-0056", "section": "service", "who": "reader", "text": "На горе святей прославльшася:"},
  {"id": "cu-str-0057", "section": "service", "who": "reader", "text": "Песнь 9. Ирмос:"},
  {"id": "cu-str-0058", "section": "service", "who": "reader", "text": "Чужде матерем девство, / и странно девам деторождение; / на Тебе, Богородице, / обоя устроишася. / Тем Тя, вся племена земная, / непрестанно величаем."},
  {"id": "cu-str-0059", "section": "service", "who": "reader", "text": "Чужде есть нечестивым целомудрие, / и странно праведником законопреступление, / Иосиф же великий уклонися греха, / и целомудрия бысть образ, / и подобие воистинну Христово."},
  {"id": "cu-str-0060", "section": "service", "who": "reader", "text": "Чужде есть беззаконником благозаконие, / и странно неверным Богоразумие: / иудее же сия отринуша за беззаконие. / Темже и едини сами наследоваша, якоже смоковница, клятву."},
  {"id": "cu-str-0061", "section": "service", "who": "reader", "text": "Взалка человеческаго спасения, / хлеб сый жизни, Христос и Бог мой. / Темже смоковницу предварив, безплодное соборище, / листвием обрастшую законно, яко виде, проклят."},
  {"id": "cu-str-0062", "section": "service", "who": "reader", "text": "Законное неплодие проклял еси, / яко листвие процветающее писменосенный разум, / плодов же дел не имущее за беззаконие: / нас же всех благодати сынов, Спасе благослови."},
  {"id": "cu-str-0063", "section": "service", "who": "reader", "text": "Жезл убо Моисеов древле в змию, / Ааронов же жезл в зелено преложися, и процвете листвие: / неплодное же изсохшее соборище законопреступное, / в неплодную преложися смоковницу."},
  {"id": "cu-str-0064", "section": "service", "who": "reader", "text": "Готови Иудее священники твоя, и устрой руце к богоубийству: / се бо прииде кроткий и молчаливый на страсть, / Агнец сый и Пастырь наш, Христос Царь Израилев."},
  {"id": "cu-str-0065", "section": "service", "who": "reader", "text": "Приими Иудее Царя, / се бо на страсть приходит волею, да постраждет, / и спасет зовущия непрестанно: / благословен Грядый спасти Крестом всяческая."},
  {"id": "cu-str-0066", "section": "service", "who": "reader", "text": "Обратил есть Иудее, праздники твоя в плачь Владыка, по пророчеству: / богоубийца бо показалася еси обращшаго древле камень, / и несекомый во источники водныя и езера, якоже поет Давид."},
  {"id": "cu-str-0067", "section": "service", "who": "reader", "text": "Слава: Чужде есть беззаконным, / еже Тя славити безначальное Существо, / Отца, и Сына, и Святаго Духа, несозданное вседержительство, / Имже весь мир соделася, манием Божественныя державы Твоея."},
  {"id": "cu-str-0068", "section": "service", "who": "reader", "text": "И ныне: Приводим в молитву Богородицу: / Тоя молитвами и апостол Твоих, / общники ны сотвори Владыко благих Твоих, / и светлости сподоби Спасе Воскресения Твоего."},
  {"id": "cu-str-0069", "section": "service", "who": "rubric", "text": "И паки ирмос тойже:"},
  {"id": "cu-str-0070", "section": "service", "who": "reader", "text": "Чужде матерем:"},
  {"id": "cu-str-0071", "section": "service", "who": "rubric", "text": "Таже и прочее обычно. И отпуст."},
  {"id": "cu-str-0072", "section": "service", "who": "rubric", "text": "Ведомо буди, яко в сию святую Великую седмицу единою совершаем Псалтирь, и глаголем на Утрени кафисмы три, и на часех, 3-м и 6-м, две. И совершаются в среду. В Великую же Субботу стихословятся Непорочны, в Вечернях же глаголем обычно: Ко Господу внегда скорбети ми:"},
  {"id": "cu-str-0073", "section": "service", "who": "reader", "text": "ВО СВЯТЫЙ И ВЕЛИКИЙ ПОНЕДЕЛЬНИК НА УТРЕНИ,"},
  {"id": "cu-str-0074", "section": "service", "who": "rubric", "text": "по шестопсалмии поем"},
  {"id": "cu-str-0075", "section": "service", "who": "reader", "text": "Аллилуиа,"},
  {"id": "cu-str-0076", "section": "service", "who": "rubric", "text": "на глас 8, велегласно, и со сладкопением, и поем тропарь косно и велегласно, и со сладкопением равно. Глас 8:"},
  {"id": "cu-str-0077", "section": "service", "who": "reader", "text": "Тропарь, глас 8 Се Жених грядет в полунощи, / и блажен раб, егоже обрящет бдяща: / недостоин же паки, егоже обрящет унывающа. / блюди убо душе моя, / не сном отяготися, / да не смерти предана будеши, / и Царствия вне затворишися, / но воспряни зовущи: / Свят, Свят, Свят еси Боже, / Богородицею помилуй нас. (3)"},
  {"id": "cu-str-0078", "section": "service", "who": "rubric", "text": "Таже обычное стихословие с поклоны."},
  {"id": "cu-str-0079", "section": "service", "who": "reader", "text": "По 1-м стихословии седален, глас 1. Подобен: Гроб Твой:"},
  {"id": "cu-str-0080", "section": "service", "who": "reader", "text": "Страдания честная настоящий день, / якоже светила совершенная, возсиявают миру: / Христос бо грядет страдати благостию, / вся содержай дланию, изволяет простретися на Древе, / еже спасти человека."},
  {"id": "cu-str-0081", "section": "service", "who": "reader", "text": "Слава, и ныне, тойже."},
  {"id": "cu-str-0082", "section": "service", "who": "reader", "text": "По 2-м стихословии седален, глас 1. Подобен:"},
  {"id": "cu-str-0083", "section": "service", "who": "reader", "text": "Невидимый Судие, в плоти како виден был еси, / и идеши от мужей беззаконных убиен быти, / наше осуждение осуждаяй страстию Твоею? / Темже хвалу, величие и славу возсылающе власти Твоей Слове, согласно приносим."},
  {"id": "cu-str-0084", "section": "service", "who": "reader", "text": "Слава, и ныне, тойже."},
  {"id": "cu-str-0085", "section": "service", "who": "reader", "text": "По 3-м стихословии седален, глас 8. Подобен: Премудрости:"},
  {"id": "cu-str-0086", "section": "service", "who": "reader", "text": "Страстей Господних начатки, / настоящий день светлоносит. / Приидите убо празднолюбцы, усрящим песньми: / Создатель бо грядет Крест прияти, испытания и раны, Пилатом судимь. / Темже и от раба ударен быв по главе, / вся терпит, да спасет человека. / Сего ради возопиим Ему: / Человеколюбче Христе Боже, / прегрешений даруй оставление, / покланяющимся верою пречистым страстем Твоим."},
  {"id": "cu-str-0087", "section": "service", "who": "reader", "text": "Слава, и ныне, тойже."},
  {"id": "cu-str-0088", "section": "service", "who": "rubric", "text": "И абие посем чтение в толковании Евангелия еже от Матфеа. И Слово Иоанна Златоустаго о изсохшей смоковнице, емуже начало:"},
  {"id": "cu-str-0089", "section": "service", "who": "reader", "text": "Якоже убо видя:"},
  {"id": "cu-str-0090", "section": "service", "who": "rubric", "text": "И слово Дамаскиново о изсохшей смоковнице, и о притчи винограда."},
  {"id": "cu-str-0091", "section": "service", "who": "rubric", "text": "Таже,"},
  {"id": "cu-str-0092", "section": "service", "who": "reader", "text": "И о сподобитися нам:"},
  {"id": "cu-str-0093", "section": "service", "who": "reader", "text": "Евангелие от Матфеа, зачало 84: [Мф. 21, 18 – 43.]"},
  {"id": "cu-str-0094", "section": "service", "who": "reader", "text": "Во время оно, возвращься Иисус во град, взалка. И узрев смоковницу едину при пути, прииде к ней, и ничтоже обрете на ней, токмо листвие едино, и глагола ей: да николиже от тебе плода будет во веки. И абие изсше смоковница. И видевше ученицы дивишася, глаголюще: како абие изсше смоковница? Отвещав же Иисус рече им: аминь глаголю вам, аще имате веру, и не усумнитеся, не токмо смоковничное сотворите, но аще и горе сей речете: двигнися, и верзися в море, будет. И вся, елика аще воспросите в молитве верующе, приимете. И пришедшу Ему в церковь, приступиша к Нему учащу архиерее и старцы людстии, глаголюще: коею властию сия твориши? И кто Ти даде власть сию? Отвещав же Иисус, рече им: вопрошу вы и Аз слово едино: еже аще речете Мне, и Аз вам реку, коею властию сия творю. Крещение Иоанново откуду бе; с небесе ли, или от человек? Они же помышляху в себе, глаголюще: аще речем, с небесе: речет нам, почто убо не веровасте ему? Аще ли речем, от человек: боимся народа: вси бо имут Иоанна яко пророка. И отвещавше Иисусови реша: не вемы. Рече им и Той: ни Аз вам глаголю, коею властию сия творю. Что же ся вам мнит? Человек некий имяше два сына, и пришед к первому, рече: чадо, иди днесь, делай в винограде моем. Он же отвещав, рече: не хощу. Последи же раскаявся, иде. И приступль к другому, рече такоже. Он же отвещав рече: аз, господи, иду. И не иде. Кий от обою сотвори волю отчу? Глаголаша Ему: первый. Глагола им Иисус: аминь глаголю вам, яко мытари и любодейцы варяют вы в Царствии Божии. Прииде бо к вам Иоанн Креститель путем праведным, и не веровасте ему, мытари же и любодейцы вероваша ему: вы же видевше, не раскаястеся последи, веровати ему. Ину притчу слышите: человек некий бе домовит, иже насади виноград, и оплотом огради его, и ископа в нем точило, и созда столп, и вдаст и делателем, и отыде. Егда же приближися время плодов, посла рабы своя к делателем прияти плоды его. И емше делателе рабы его, оваго убо биша, оваго же убиша, оваго же камением побиша. Паки посла ины рабы множайша первых: и сотвориша им такоже. Последи же посла к ним сына своего, глаголя: усрамятся сына моего. Делателе же видевше сына, реша в себе: сей есть наследник, приидите, убием его, и удержим достояние его. И емше его, изведоша вон из винограда, и убиша. Егда убо приидет господин винограда, что сотворит делателем тем? Глаголаша Ему: злых зле погубит их, и виноград предаст иным делателем, иже воздадят ему плоды во времена своя. Глагола им Иисус: несте ли чли николиже в Писаниих: камень, егоже не в ряду сотвориша зиждущии, сей бысть во главу угла? От Господа бысть сей, и есть дивна во очию вашею. Сего ради глаголю вам, яко отымется от вас Царствие Божие, и дастся языку творящему плоды его."},
  {"id": "cu-str-0095", "section": "service", "who": "rubric", "text": "Посем псалом 50. Таже,"},
  {"id": "cu-str-0096", "section": "service", "who": "reader", "text": "Спаси Боже люди Твоя: Господи помилуй, 12."},
  {"id": "cu-str-0097", "section": "service", "who": "reader", "text": "Трипеснец, творение господина Космы,"},
  {"id": "cu-str-0098", "section": "service", "who": "rubric", "text": "егоже краестрочие:"},
  {"id": "cu-str-0099", "section": "service", "who": "reader", "text": "Ти девтера, си есть:"},
  {"id": "cu-str-0100", "section": "service", "who": "rubric", "text": "во вторый день, еже есть понедельник. Ирмос по дважды, тропари на 12. Припев:"},
  {"id": "cu-str-0101", "section": "service", "who": "reader", "text": "Слава Тебе Боже наш, слава Тебе."},
  {"id": "cu-str-0102", "section": "service", "who": "rubric", "text": "[Сей во всю седмицу]. Последи ирмос, оба лика вкупе. Глас 2."},
  {"id": "cu-str-0103", "section": "service", "who": "reader", "text": "Песнь 1. {Τ} Ирмос:"},
  {"id": "cu-str-0104", "section": "service", "who": "reader", "text": "Непроходимое волнящееся море, / Божиим Своим велением изсушившему, / и пешешествовати сквозе е Израильтеския люди наставльшему, / Господеви поим, славно бо прославися. {Η}"},
  {"id": "cu-str-0105", "section": "service", "who": "reader", "text": "Неизреченное Слова Божия схождение, / еже Христос Тойжде есть Бог и Человек, / еже Бог невосхищением быти непщевав, / внегда воображатися рабом, показует учеником, / славно бо прославися. {Δ}"},
  {"id": "cu-str-0106", "section": "service", "who": "reader", "text": "Послужити Сам приидох, / егоже зраком Создатель волею обложен есмь, / обнищавшему Адаму, богатствуяй Божеством, / положити хотяй Мою душу избавление зань, / Иже безстрастный Божеством."},
  {"id": "cu-str-0107", "section": "service", "who": "reader", "text": "Кондак, глас 8. Подобен: Яко начатки:"},
  {"id": "cu-str-0108", "section": "service", "who": "reader", "text": "Иаков рыдаше Иосифова лишения, / и доблий седяше на колеснице, яко царь почитаемь: / египтяныни бо тогда сластем не поработав, / воспрославляшеся от Ведущаго человеческая сердца, / и Посылающаго венец нетленный. Икос:"},
  {"id": "cu-str-0109", "section": "service", "who": "reader", "text": "На рыдание ныне приложим рыдание, / и излием слезы со Иаковом, / плачущеся Иосифа приснопамятнаго и целомудреннаго, / порабощеннаго убо телом, душу же непорабощену соблюдшаго, / и Египтом всем царствовавшаго: / Бог бо подает рабом Своим венец нетленный. Синаксарий."},
  {"id": "cu-str-0110", "section": "service", "who": "reader", "text": "Песнь 8. {Ε} Ирмос:"},
  {"id": "cu-str-0111", "section": "service", "who": "reader", "text": "Устрашися отроков благочестивых, / сообразнаго души несквернаго тела, / и устранися воспитанный в безмерном веществе, / неутружден огнь, / Присноживущу же изувядшу пламеню, / вечнующая песнь воспевашеся: / Господа, вся дела, пойте, / и превозносите во вся веки. {Υ}"},
  {"id": "cu-str-0112", "section": "service", "who": "reader", "text": "Вас тогда Моих учеников познают вси, аще Моя заповеди соблюдете, / глаголет Спас другом, ко страсти идый: / мир имейте в себе, и во всех, и смиренная мудрствующе возвыситеся: / и Господа знающе Мя пойте, и превозносите во вся веки. {Τ}"},
  {"id": "cu-str-0113", "section": "service", "who": "reader", "text": "Чина сопротивна вам языческа, да есть держава купнородных: / не жребий бо Мой, мучительство же разум самоизбранный. / Иже убо предызящный в вас быти хотяй других, / да есть всех последнейший: / и Господа знающе Мя пойте, и превозносите во вся веки."},
  {"id": "cu-str-0114", "section": "service", "who": "reader", "text": "Хвалим, благословим, покланяемся Господеви, поюще, и превозносяще во вся веки. И паки ирмос."},
  {"id": "cu-str-0115", "section": "service", "who": "reader", "text": "Честнейшую не поем."},
  {"id": "cu-str-0116", "section": "service", "who": "reader", "text": "Песнь 9. {Ε} Ирмос:"},
  {"id": "cu-str-0117", "section": "service", "who": "reader", "text": "Возвеличил еси Христе, рождшую Тя Богородицу, / от Неяже Создателю наш, / в подобострастное нам облеклся еси тело, / наших прегрешений решительное: / Сию ублажающе, вси роди, / Тебе величаем. {Ρ}"},
  {"id": "cu-str-0118", "section": "service", "who": "reader", "text": "Скверну всю страстную отринувше, / достойный Божественнаго Царствия разум восприимем благомудрственный, / Твоим апостолом предрекл еси, всех Премудросте: / в немже прославитеся, светящеся солнца светозарнее. {Α}"},
  {"id": "cu-str-0119", "section": "service", "who": "reader", "text": "Взирающе на Мя, рекл еси Господи Твоим учеником, / не мудрствуйте высокая, но соотведитеся смиренными: / Мою, юже пию, пийте чашу, / яко да во Царствии Отца со Мною прославитеся. Таже ирмос:"},
  {"id": "cu-str-0120", "section": "service", "who": "reader", "text": "Возвеличил еси Христе:"},
  {"id": "cu-str-0121", "section": "service", "who": "rubric", "text": "И поклон до земли."},
  {"id": "cu-str-0122", "section": "service", "who": "rubric", "text": "Ексапостиларий глаголем трижды, косно и со сладкопением. Сей же глаголется до Великаго Четвертка, поется же посреде церкве от певца, и противу глашается от нас:"},
  {"id": "cu-str-0123", "section": "service", "who": "reader", "text": "Ексапостиларий: Чертог Твой вижду Спасе мой, украшенный, / и одежды не имам, да вниду вонь: / просвети одеяние души моея / Светодавче, и спаси мя."},
  {"id": "cu-str-0124", "section": "service", "who": "reader", "text": "На хвалитех стихиры самогласны на 4, глас 1:"},
  {"id": "cu-str-0125", "section": "service", "who": "reader", "text": "Грядый Господь к вольной страсти, / апостолом глаголаше на пути: / се восходим во Иерусалим, / и предастся Сын Человеческий, / якоже есть писано о Нем. / Приидите убо и мы, очищенными смыслы, / сшествуим Ему, и сраспнемся, и умертвимся Его ради житейским сластем, / да и оживем с Ним, и услышим вопиюща Его: / не ктому в земный Иерусалим, за еже страдати, / но восхожду ко Отцу Моему, и Отцу вашему, / и Богу Моему, и Богу вашему, / и совозвышу вас в горний Иерусалим, / в Царство Небесное. (2) Глас 5:"},
  {"id": "cu-str-0126", "section": "service", "who": "reader", "text": "Достигше вернии спасительную страсть Христа Бога, / неизреченное Его долготерпение прославим: / яко да благоутробием Своим совоздвигнет и нас умерщвленных грехом, / яко Благ и Человеколюбец. (2)"},
  {"id": "cu-str-0127", "section": "service", "who": "reader", "text": "Слава, и ныне, глас тойже: Господи, грядый к страданию, / Твоя утверждая ученики, глаголал еси особь прием их: / како глагол Моих не помните, яже прежде рекох вам? / Яко всякому пророку несть писано, токмо во Иерусалиме убиену быти. / Ныне убо время настоит, еже рекох вам: / се бо предаюся рукама грешных поруган быти, / иже и кресту Мя пригвоздивше, и погребению предавше, / омерзена вменят яко мертва. / Обаче дерзайте: тридневен бо востану / в радость верных, и жизнь вечную."},
  {"id": "cu-str-0128", "section": "service", "who": "reader", "text": "На стиховне самогласен. Глас 5:"},
  {"id": "cu-str-0129", "section": "service", "who": "reader", "text": "Господи, к таинству неизглаголанному Твоего смотрения, / не довлеющи сынов Зеведеовых мати, прошаше Тя, / временнаго царства почести дароватися чадом ея, / но вместо тоя, чашу смерти обещал еси пити другом Твоим, / юже чашу прежде сих пити Сам глаголал еси, / грехов очищение. / Темже Тебе вопием: / спасение душ наших, слава Тебе. Стих:"},
  {"id": "cu-str-0130", "section": "service", "who": "reader", "text": "Исполнихомся заутра милости Твоея, Господи, возрадовахомся, и возвеселихомся: во вся дни наша возвеселихомся. За дни, в няже смирил ны еси, лета в няже видехом злая. И призри на рабы Твоя, и на дела Твоя, / и настави сыны их."},
  {"id": "cu-str-0131", "section": "service", "who": "reader", "text": "Господи, совершеннейшая мудрствовати, Твоя наказуя ученики, / не уподобитися языком глаголал еси, / во еже обладати меньшими: / не тако бо будет вам Моим учеником, / яко нищий хотя есмь. / Первый убо вас, да будет всем слуга: / начальствуяй же яко начальствуемый, / предызящный же яко последнейший. / Ибо приидох Сам обнищавшему Адаму послужити, / и избавление дати за многих душу Мою, / вопиющих Ми: слава Тебе. Стих:"},
  {"id": "cu-str-0132", "section": "service", "who": "reader", "text": "И буди светлость Господа Бога нашего на нас, и дела рук наших исправи на нас, / и дело рук наших исправи. Глас 8:"},
  {"id": "cu-str-0133", "section": "service", "who": "reader", "text": "Изсохшия смоковницы за неплодие, / прещения убоявшеся братие, / плоды достойны покаяния принесем Христу, / подающему нам велию милость."},
  {"id": "cu-str-0134", "section": "service", "who": "reader", "text": "Слава, и ныне, глас тойже: Вторую Еву египтяныню обрет змий глаголы, / тщашеся ласканьми запяти Иосифа, / но той оставив ризу, бежа греха: / и наг не стыдяшеся, якоже первозданный прежде преслушания. / Того молитвами Христе помилуй нас. Таже:"},
  {"id": "cu-str-0135", "section": "service", "who": "reader", "text": "Благо есть:"},
  {"id": "cu-str-0136", "section": "service", "who": "rubric", "text": "И прочая по обычаю с поклоны."},
  {"id": "cu-str-0137", "section": "service", "who": "reader", "text": "Таже отпуст: Грядый Господь на вольную страсть, нашего ради спасения, Христос, истинный Бог наш, молитвами пречистыя Своея Матере, святых славных и всехвальных Апостол, святых праведных Богоотец Иоакима и Анны, и всех святых, помилует и спасет нас, яко Благ и Человеколюбец."},
  {"id": "cu-str-0138", "section": "service", "who": "rubric", "text": "Сей же отпуст глаголется во вторник и в среду."},
  {"id": "cu-str-0139", "section": "service", "who": "rubric", "text": "Ведомо же буди, яко на 1-м часе и 9-м Псалтирь не глаголем в Великую седмицу: но точию глаголются трипсалмны, по обычаю. Третий же час и шестый поем со Псалтирем. Чтется же и Четвероевангелие, в Понедельник, во Вторник и в Среду совершается. При часе 3-м дне ударяет параекклисиарх в било, яко же есть обычай. И собравшеся в церковь, поем 3-й час, с кафисмою: и творяще обычныя поклоны. Таже тропарь:"},
  {"id": "cu-str-0140", "section": "service", "who": "choir", "text": "Господи, Иже Пресвятаго Твоего Духа: и"},
  {"id": "cu-str-0141", "section": "service", "who": "choir", "text": "Богородице Ты еси лоза:"},
  {"id": "cu-str-0142", "section": "service", "who": "rubric", "text": "поклоны 3. И абие украшену аналогию, положат на нем верху святое Четвероевангелие, и двема лампадома возжженнома. Всем же стоящим откровенными главами. Священник же кадит храм весь, и братию. А на 6-м часе кадит токмо Евангелие. На 9-м же часе Евангелие кадит, и храм весь, и братию: И тако чтет Евангелие. По скончании же чтения Евангелия глаголем:"},
  {"id": "cu-str-0143", "section": "service", "who": "priest", "text": "Господь Бог благословен:"},
  {"id": "cu-str-0144", "section": "service", "who": "rubric", "text": "И прочее последование. Глаголется и кондак дне:"},
  {"id": "cu-str-0145", "section": "service", "who": "priest", "text": "Иаков рыдаше:"},
  {"id": "cu-str-0146", "section": "service", "who": "rubric", "text": "И обычныя поклоны. И абие начинаем шестый час."},
  {"id": "cu-str-0147", "section": "service", "who": "priest", "text": "Приидите поклонимся:"},
  {"id": "cu-str-0148", "section": "service", "who": "rubric", "text": "трижды, и псалмы обычныя: Кафисму рядовую. Таже тропарь:"},
  {"id": "cu-str-0149", "section": "service", "who": "priest", "text": "Иже в шестый день же и час:"},
  {"id": "cu-str-0150", "section": "service", "who": "rubric", "text": "и Богородичен:"},
  {"id": "cu-str-0151", "section": "service", "who": "priest", "text": "Яко не имамы дерзновения: и поклоны 3."},
  {"id": "cu-str-0152", "section": "service", "who": "priest", "text": "НА ШЕСТОМ ЧАСЕ"},
  {"id": "cu-str-0153", "section": "service", "who": "rubric", "text": "И абие начинаем шестый час."},
  {"id": "cu-str-0154", "section": "service", "who": "priest", "text": "Приидите поклонимся:"},
  {"id": "cu-str-0155", "section": "service", "who": "rubric", "text": "трижды, и псалмы обычныя: Кафисму 8-ю. Таже тропарь:"},
  {"id": "cu-str-0156", "section": "service", "who": "priest", "text": "Иже в шестый день же и час:"},
  {"id": "cu-str-0157", "section": "service", "who": "rubric", "text": "и Богородичен:"},
  {"id": "cu-str-0158", "section": "service", "who": "priest", "text": "Яко не имамы дерзновения: и поклоны 3."},
  {"id": "cu-str-0159", "section": "service", "who": "priest", "text": "Таже тропарь пророчества, глас 6:"},
  {"id": "cu-str-0160", "section": "service", "who": "priest", "text": "Душею сокрушенною припадаем Тебе, / и молим Тя Спасе мира: / Ты бо еси Бог кающихся."},
  {"id": "cu-str-0161", "section": "service", "who": "priest", "text": "Слава, и ныне, тойже."},
  {"id": "cu-str-0162", "section": "service", "who": "priest", "text": "Прокимен, псалом 125, глас 4:"},
  {"id": "cu-str-0163", "section": "service", "who": "priest", "text": "Внегда возвратити Господу / плен Сионь. Стих:"},
  {"id": "cu-str-0164", "section": "service", "who": "priest", "text": "Тогда исполнишася радости уста наша."},
  {"id": "cu-str-0165", "section": "service", "who": "priest", "text": "Пророчества Иезекиилева чтение: [Глава 1, ст. 1 – 20]"},
  {"id": "cu-str-0166", "section": "service", "who": "priest", "text": "Бысть в тридесятое лето, в четвертый месяц, в пятый день месяца, и аз бых посреде пленения при реце Ховар: и отверзошася небеса, и видех видения Божия. В пятый день месяца, сие лето пятое пленения царя Иоакима. И бысть слово Господне ко Иезекиилю сыну Вузиеву, священнику в земли халдейстей при реце Ховар. И бысть на мне рука Господня. И видех, и се дух воздвизаяйся, грядяше от севера, и облак великий в нем, и свет окрест его и огнь блистаяйся. И посреде его яко видение илектра посреде огня, и свет в нем: посреде яко подобие четырех животных: и сие видение их, яко подобие человека в них. И четыре лица единому, и четыре крила единому. И голени их правы, и пернаты ноги их, и искры яко блистающаяся медь, и легка крила их. И рука человеча под крилами их на четырех странах их. И лица их и крила их четырех держащаяся друг друга, лица же их четырех не обращахуся, внегда ходити им: коеждо прямо лица своего хождаху. И подобие лиц их, лице человечее, и лице львово одесную четырем, и лице тельчее ошуюю четырем, и лице орлее четырем. [И лица их] и крила их простерты свыше четырем, коемуждо два сопряжена друг ко другу, и два покрываху верху телесе их, и коеждо прямо лицу своему идяше. Идеже аще бяше дух шествуяй, идяху, и не обращахуся. И посреде животных видение яко углия огня горящаго, яко видение свещ сообращающихся посреде животных, и свет огня, и от огня исхождаше яко молния. И животная течаху, и обращахуся, яко видение везеково. И видех, и се коло едино на земли держащееся животных четырех. И видение колес, и сотворение их, яко видение фарсиса, и подобие едино четырем: и дело их бяше, якоже аще бы было коло в колеси. На четыри страны их шествоваху: не обращахуся, внегда шествовати им. Ниже хребты их, и высота бяше им: и видех та, и плещи их исполнены очес окрест четырем. И внегда шествовати животным, шествоваху и колеса держащеся их: и внегда воздвизатися животным от земли, воздвизахуся и колеса. Идеже аще бяше облак, тамо бяше и дух, еже шествовати: шествоваху и животная, и колеса воздвизахуся с ними, зане дух жизни бяше в колесех."},
  {"id": "cu-str-0167", "section": "service", "who": "priest", "text": "Прокимен, псалом 126, глас 4:"},
  {"id": "cu-str-0168", "section": "service", "who": "priest", "text": "Аще не Господь созиждет дом, / всуе трудишася зиждущии. Стих:"},
  {"id": "cu-str-0169", "section": "service", "who": "priest", "text": "Аще не Господь сохранит град, всуе бде стрегий."},
  {"id": "cu-str-0170", "section": "service", "who": "rubric", "text": "И чтется Евангелие по предписанному чину. По чтении же,"},
  {"id": "cu-str-0171", "section": "service", "who": "priest", "text": "Скоро да предварят ны щедроты Твоя Господи:"},
  {"id": "cu-str-0172", "section": "service", "who": "rubric", "text": "Трисвятое, с поклоны. По"},
  {"id": "cu-str-0173", "section": "service", "who": "priest", "text": "Отче наш: Кондак дне."},
  {"id": "cu-str-0174", "section": "service", "who": "priest", "text": "Господи помилуй,"},
  {"id": "cu-str-0175", "section": "service", "who": "rubric", "text": "40. И прочее по обычаю, и отпуст."},
  {"id": "cu-str-0176", "section": "service", "who": "rubric", "text": "Ведомо же буди: яко Евангелие от Матфеа все чтется, подобне и от Марка, и от Луки: от Иоанна же чтется до начала святых страстей, яве яко до"},
  {"id": "cu-str-0177", "section": "service", "who": "priest", "text": "Ныне прославися Сын Человеческий:"},
  {"id": "cu-str-0178", "section": "service", "who": "rubric", "text": "Чтется же тако в трех днех, сиречь, в Понедельник, во Вторник, в Среду: И совершается в Среду на 9-м часе. Бывают же от Луки чтения три. Прочая же по два. Вкупе всех чтений девять, и вящше ничтоже. Девятый же час трех дней стихословия не имать, якоже речеся. Но по трипсалмии поется от учиненнаго монаха:"},
  {"id": "cu-str-0179", "section": "service", "who": "priest", "text": "Иже в девятый час: Слава, и ныне: Иже нас ради рождейся от Девы:"},
  {"id": "cu-str-0180", "section": "service", "who": "rubric", "text": "И бывает чтение в Четвероевангелии: По немже глаголем:"},
  {"id": "cu-str-0181", "section": "service", "who": "reader", "text": "Не предаждь нас до конца:"},
  {"id": "cu-str-0182", "section": "service", "who": "rubric", "text": "Трисвятое с поклоны. По"},
  {"id": "cu-str-0183", "section": "service", "who": "reader", "text": "Отче наш: Кондак дне."},
  {"id": "cu-str-0184", "section": "service", "who": "reader", "text": "Во Царствии Твоем:"},
  {"id": "cu-str-0185", "section": "service", "who": "rubric", "text": "И прочее последование, яко обычно. Глаголем же и кондак дне. Присовокупляем же и Вечерню."},
  {"id": "cu-str-0186", "section": "service", "who": "priest", "text": "ВО СВЯТЫЙ И ВЕЛИКИЙ ПОНЕДЕЛЬНИК ВЕЧЕРА,"},
  {"id": "cu-str-0187", "section": "service", "who": "rubric", "text": "по предначинательном псалме обычное стихословие:"},
  {"id": "cu-str-0188", "section": "service", "who": "priest", "text": "Ко Господу внегда скорбети ми, воззвах: На"},
  {"id": "cu-str-0189", "section": "service", "who": "priest", "text": "Господи воззвах,"},
  {"id": "cu-str-0190", "section": "service", "who": "rubric", "text": "поставим стихов 10, и поем стихиры самогласны дне 4 по дважды, а два по единожды, глас 1:"},
  {"id": "cu-str-0191", "section": "service", "who": "priest", "text": "Грядый Господь к вольней страсти, / апостолом глаголаше на пути: / се восходим во Иерусалим, / и предастся Сын Человеческий, / якоже есть писано о Нем. / Приидите убо и мы, очищенными смыслы, сшествуим Ему, / и сраспнемся, и умертвимся Его ради житейским сластем, / да и оживем с Ним, и услышим вопиюща Его: / не ктому в земный Иерусалим за еже страдати, / но восхожду ко Отцу Моему и Отцу вашему, / и Богу Моему и Богу вашему, / и совозвышу вас в горний Иерусалим, / в Царство Небесное. (2) Глас 5:"},
  {"id": "cu-str-0192", "section": "service", "who": "priest", "text": "Достигше вернии спасительную страсть Христа Бога, / неизреченное Его долготерпение прославим: / яко да благоутробием Своим / совоздвигнет и нас умерщвленных грехом, / яко Благ и Человеколюбец. (2)"},
  {"id": "cu-str-0193", "section": "service", "who": "priest", "text": "Господи грядый к страданию, / Твоя утверждая ученики, / глаголал еси особь прием их: / како глагол Моих не помните, / яже прежде рекох вам? / Яко всякому пророку несть писано, / токмо во Иерусалиме убиену быти. / Ныне убо время настоит, еже рекох вам: / се бо предаюся рукама грешных поруган быти, / иже и кресту Мя пригвоздивше, и погребению предавше, / омерзена вменят яко мертва. / Обаче дерзайте, тридневен бо востану, / в радость верных, и жизнь вечную. (2)"},
  {"id": "cu-str-0194", "section": "service", "who": "priest", "text": "Господи, к таинству неизглаголанному Твоего смотрения, / не довлеющи сынов Зеведеовых мати, прошаше Тя, / временнаго царства почести дароватися чадом ея, / но вместо тоя, чашу смерти обещал еси пити другом Твоим, / юже чашу прежде сих пити Сам глаголал еси, / грехов очищение. / Темже Тебе вопием: / спасение душ наших, слава Тебе. (2)"},
  {"id": "cu-str-0195", "section": "service", "who": "priest", "text": "Господи, совершеннейшая мудрствовати, / Твоя наказуя ученики, / не уподобитися языком глаголал еси, / во еже обладати меньшими: / не тако бо будет вам Моим учеником, / яко нищий хотя есмь. / Первый убо вас, да будет всем слуга: / начальствуяй же, яко начальствуемый: / предызящный же, яко последнейший. / Ибо приидох Сам обнищавшему Адаму послужити, / и избавление дати за многих душу Мою, / вопиющих Ми: слава Тебе. Глас 8:"},
  {"id": "cu-str-0196", "section": "service", "who": "priest", "text": "Изсохшия смоковницы за неплодие, / прещения убоявшеся братие, / плоды достойны покаяния принесем Христу, / подающему нам велию милость."},
  {"id": "cu-str-0197", "section": "service", "who": "priest", "text": "Слава, и ныне, глас тойже: Вторую Еву египтяныню обрет змий глаголы, / тщашеся ласканьми запяти Иосифа, / но той оставив ризу, бежа греха, / и наг не стыдяшеся, якоже первозданный прежде преслушания. / Того молитвами, Христе, помилуй нас."},
  {"id": "cu-str-0198", "section": "service", "who": "rubric", "text": "Таже вход со Евангелием."},
  {"id": "cu-str-0199", "section": "service", "who": "priest", "text": "Свете тихий:"},
  {"id": "cu-str-0200", "section": "service", "who": "priest", "text": "Прокимен, псалом 127. Глас 6: Благословит тя Господь от Сиона, / и узриши благая Иерусалима. Стих:"},
  {"id": "cu-str-0201", "section": "service", "who": "priest", "text": "Блажени вси боящиися Господа, ходящии в путех Его."},
  {"id": "cu-str-0202", "section": "service", "who": "priest", "text": "Исхода чтение: [Глава 1, ст. 1 – 20]"},
  {"id": "cu-str-0203", "section": "service", "who": "priest", "text": "Сия имена сынов Израилевых, входящих во Египет вкупе со Иаковом отцем их, кийждо со всем домом своим внидоша: Рувим, Симеон, Левий, Иуда, Иссахар, Завулон и Вениамин, Дан и Неффалим, Гад и Асир. Иосиф же бяше во Египте. Бяше же всех душ изшедших из Иакова, седмьдесят пять. Умре же Иосиф, и вся братия его, и весь род оный. Сынове же Израилевы возрастоша, и умножишася, и мнози быша, и укрепишася зело зело: умножи же их земля. Воста же царь ин во Египте, иже не знаше Иосифа. Рече же языку своему: се род сынов Израилевых великое множество, и укрепляется паче нас. Приидите убо прехитрим их, да не когда умножатся; и егда аще приключится нам брань, приложатся и сии к супостатом, и одолевше нам, изыдут из земли [нашея]. И пристави над ними приставники дел, да озлобят их в делех: и создаша грады тверды фараону, Пифо, и Рамесси, и Он, иже есть Илиополь. Поелику же их смиряху, толико множайшии бываху, и укрепляхуся зело зело. И гнушахуся египтяне сынми Израилевыми. И насилие творяху египтяне сыном Израилевым нуждею. И болезненну тем жизнь творяху в делех жестоких, брением, и плинфоделанием, и всеми делы, яже в полях, во всех делех, имиже порабощаху их с нуждею."},
  {"id": "cu-str-0204", "section": "service", "who": "priest", "text": "И рече царь египетский бабам еврейским: единой их имя, Сепфора, и имя второй, Фуа. И рече [им]: егда бабите евреаныням, и суть к рождению, аще убо мужеский пол будет, убивайте его, аще же женский, снабдевайте его. Убояшася же бабы Бога, и не сотвориша, якоже повеле им царь египетский, и живляху мужеский пол. Призва же царь египетский бабы, и рече им: что яко сотвористе вещь сию, и оживляете мужеский пол? Рекоша же бабы фараону: не яко жены египтяныни, тако и жены евреаныни: раждают бо прежде неже внити к ним бабам, и раждаху. Благо же творяше Бог бабам, и множахуся людие, и укрепляхуся зело."},
  {"id": "cu-str-0205", "section": "service", "who": "priest", "text": "Прокимен, псалом 128, глас 6:"},
  {"id": "cu-str-0206", "section": "service", "who": "priest", "text": "Благословихом вы / во имя Господне. Стих:"},
  {"id": "cu-str-0207", "section": "service", "who": "priest", "text": "Множицею брашася со мною от юности моея."},
  {"id": "cu-str-0208", "section": "service", "who": "priest", "text": "Иова чтение: [Глава 1, ст. 1 – 12]"},
  {"id": "cu-str-0209", "section": "service", "who": "priest", "text": "Человек некий бяше во стране Авситидийстей, емуже имя Иов: и бе человек он истинен, непорочен, праведен, Богочестив, удаляяйся от всякия лукавыя вещи. Быша же ему сынове седмь, и дщери три. И бяху скоти его, овец седмь тысящ, вельблюдов три тысящи: супруг волов пять сот, и ослиц пасомых пять сот, и слуг много зело, и дела велия бяху ему на земли: и бе человек оный благороднейший сущих от восток солнца. Сходящеся же сынове его друг ко другу, творяху пир на кийждо день, споемлюще вкупе и три сестры своя, ясти и пити с ними. И егда скончавашася дние пира, посылаше Иов и очищаше их, востая заутра: и приношаше о них жертвы по числу их, и тельца единаго о гресе, о душах их. Глаголаше бо Иов: негли когда сынове мои согрешиша, и в мысли своей злая помыслиша противу Бога? Тако убо творяше Иов вся дни."},
  {"id": "cu-str-0210", "section": "service", "who": "priest", "text": "И бысть яко день сей, и се приидоша ангели Божии предстати пред Господем, и диавол прииде с ними. И рече Господь диаволу: откуду пришел еси? И отвещав диавол Господеви, рече: обшед землю, и прошед поднебесную се есмь. И рече ему Господь: внял ли еси мыслию твоею на раба Моего Иова? Зане несть яко он, на земли человек непорочен, истинен, богочестив, удаляяйся от всякия лукавыя вещи. Отвеща же диавол, и рече пред Господем: еда туне Иов чтит Господа? Не Ты ли оградил еси внешняя его, и внутренняя дому его, и яже вне всех сущих его окрест? Дела же руку его благословил еси, и скоты его многи сотворил еси на земли. Но посли руку Твою, и коснися всех, яже имать: аще не в лице Тя благословит. Тогда рече Господь диаволу: се вся елика суть ему, даю в руку твою, но самого да не коснешися. И изыде диавол от Господа. Таже,"},
  {"id": "cu-str-0211", "section": "service", "who": "priest", "text": "Да исправится молитва моя:"},
  {"id": "cu-str-0212", "section": "service", "who": "priest", "text": "И посем Евангелие от Матфеа, зачало 98: [Мф. 24, 3 – 35]"},
  {"id": "cu-str-0213", "section": "service", "who": "priest", "text": "Во время оно, седящу Иисусу на горе Елеонстей, приступиша к Нему ученицы на едине, глаголюще: рцы нам, когда сия будут; и что есть знамение Твоего пришествия и кончина века? И отвещав Иисус рече им: блюдите, да никтоже вас прельстит. Мнози бо приидут во имя Мое, глаголюще: аз есмь Христос, и многи прельстят. Услышати же имате брани, и слышания бранем. Зрите, не ужасайтеся, подобает бо всем сим быти, но не тогда есть кончина. Востанет бо язык на язык, и царство на царство: и будут глади и пагубы, и труси по местом. Вся же сия начало болезнем. Тогда предадят вы в скорби, и убиют вы, и будете ненавидими всеми языки имене Моего ради. И тогда соблазнятся мнози, и друг друга предадят, и возненавидят друг друга. И мнози лжепророцы востанут и прельстят многия. И за умножение беззакония, изсякнет любы многих. Претерпевый же до конца, той спасется. И проповестся сие Евангелие Царствия по всей вселенней, во свидетелство всем языком: и тогда приидет кончина. Егда убо узрите мерзость запустения, реченную Даниилом пророком, стоящу на месте святе, иже чтет, да разумеет, тогда сущии во Иудеи да бежат на горы. И иже на крове, да не сходит взяти яже в дому его. И иже на селе, да не возвратится вспять взяти риз своих. Горе же непраздным и доящим в тыя дни. Молитеся же, да не будет бегство ваше в зиме, ни в субботу. Будет бо тогда скорбь велия, якова же несть была от начала мира доселе, ниже имать быти. И аще не быша прекратилися дние оны, не бы убо спаслася всяка плоть: избранных же ради прекратятся дние оны. Тогда аще кто речет вам: се, зде Христос, или онде, не имите веры. Востанут бо лжехристи и лжепророцы, и дадят знамения велия и чудеса, якоже прельстити, аще возможно, и избранныя. Се, прежде рех вам. Аще убо рекут вам: се, в пустыни есть, не изыдите: се, в сокровищах, не имите веры. Якоже бо молния исходит от восток и является до запад, тако будет пришествие Сына Человеческаго. Идеже бо аще будет труп, тамо соберутся орли. Абие же, по скорби дний тех, солнце померкнет, и луна не даст света своего, и звезды спаднут с небесе, и силы небесныя подвигнутся. И тогда явится знамение Сына Человеческаго на небеси, и тогда восплачутся вся колена земная, и узрят Сына Человеческаго, грядуща на облацех небесных с силою и славою многою. И послет ангелы Своя с трубным гласом велиим, и соберут избранныя Его от четырех ветр, от конец небес до конец их. От смоковницы же научитеся притчи: егда уже ваия ея будут млада, и листвие прозябнет, ведите, яко близ есть жатва. Тако и вы, егда видите сия вся, ведите, яко близ есть, при дверех. Аминь глаголю вам, не мимоидет род сей, дондеже вся сия будут. Небо и земля мимоидет, словеса же Моя не мимоидут."},
  {"id": "cu-str-0214", "section": "service", "who": "rubric", "text": "И прочее последование Преждеосвященных, по обычаю. Тако долженствует быти и в Великий Вторник, и в Великую Среду."},
  {"id": "cu-str-0215", "section": "service", "who": "rubric", "text": "Аще же несть Преждеосвященныя: Поем на"},
  {"id": "cu-str-0216", "section": "service", "who": "priest", "text": "Господи воззвах,"},
  {"id": "cu-str-0217", "section": "service", "who": "rubric", "text": "половину от стихир, на 6. Стихира, глас 1:"},
  {"id": "cu-str-0218", "section": "service", "who": "priest", "text": "Грядый Господь к вольной страсти: дважды."},
  {"id": "cu-str-0219", "section": "service", "who": "priest", "text": "Достигше вернии: дважды."},
  {"id": "cu-str-0220", "section": "service", "who": "priest", "text": "Господи, к таинству неизглаголанному: дважды."},
  {"id": "cu-str-0221", "section": "service", "who": "priest", "text": "Слава, и ныне: Господи грядый к страданию:"},
  {"id": "cu-str-0222", "section": "service", "who": "rubric", "text": "По сих вход с Евангелием: и"},
  {"id": "cu-str-0223", "section": "service", "who": "priest", "text": "Свете тихий:"},
  {"id": "cu-str-0224", "section": "service", "who": "rubric", "text": "Таже прокимен, и паремии, и Евангелие. Таже,"},
  {"id": "cu-str-0225", "section": "service", "who": "priest", "text": "Сподоби Господи: И ектения:"},
  {"id": "cu-str-0226", "section": "service", "who": "priest", "text": "Исполним вечернюю:"},
  {"id": "cu-str-0227", "section": "service", "who": "rubric", "text": "На стиховне, от техже стихир, стихира, глас 5:"},
  {"id": "cu-str-0228", "section": "service", "who": "priest", "text": "Господи совершеннейшая мудрствовати: Стих:"},
  {"id": "cu-str-0229", "section": "service", "who": "priest", "text": "К Тебе возведох очи мои:"},
  {"id": "cu-str-0230", "section": "service", "who": "rubric", "text": "И паки туюжде стихиру. Стих:"},
  {"id": "cu-str-0231", "section": "service", "who": "priest", "text": "Помилуй нас Господи: Глас 8:"},
  {"id": "cu-str-0232", "section": "service", "who": "priest", "text": "Изсохшая смоковницы: Слава, и ныне, глас тойже:"},
  {"id": "cu-str-0233", "section": "service", "who": "priest", "text": "Вторую Еву: Таже,"},
  {"id": "cu-str-0234", "section": "service", "who": "priest", "text": "Ныне отпущаеши:"},
  {"id": "cu-str-0235", "section": "service", "who": "rubric", "text": "И прочая обычная с поклоны. И по конечном Трисвятом, и по"},
  {"id": "cu-str-0236", "section": "service", "who": "priest", "text": "Отче наш: Господи помилуй,"},
  {"id": "cu-str-0237", "section": "service", "who": "rubric", "text": "12. Таже, молитва,"},
  {"id": "cu-str-0238", "section": "service", "who": "priest", "text": "Всесвятая Троице: и"},
  {"id": "cu-str-0239", "section": "service", "who": "priest", "text": "Буди имя Господне: И отпуст."},
  {"id": "cu-str-0240", "section": "service", "who": "rubric", "text": "Сице убо творим во Вторник и в Среду."},
  {"id": "cu-str-0241", "section": "service", "who": "rubric", "text": "На трапезе же ядим сухоядение, и сим удовляемся. И якоже в первую неделю святаго сего Поста: сице и в сия дни, в Великий Понедельник, во Вторник и в Среду поститися подобает."},
  {"id": "cu-str-0242", "section": "service", "who": "rubric", "text": "Ведати бо подобает, яко и Шестый великий Собор повеле, спасительныя страсти дни в посте, и молитве, и умилении сердца сотворяти верным: в полунощи же Великия Субботы, оставляти пост, Божественным евангелистом Матфею и Луце: овому убо позде в субботу глаголанием, овому же утром глубоким, медлемое нам нощи написующим."},
];

